arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *assword*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh
cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && git config user.email "rachel@beetle-in-the-anthill.local" && git -C /tmp/fw-rachel commit --amend --allow-empty --reset-author -F /tmp/msg-rachel-1.txt -q && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git -C /tmp/fw-rachel push origin HEAD:refs/heads/friend/rachel 2>&1 | tail -3
